function MyYLCToken(
  uint256 initialSupply,
  string tokenName,
  uint8 decimalUnits,
  string tokenSymbol
  ) token (initialSupply, tokenName, decimalUnits, tokenSymbol) {
  balanceOf[msg.sender] = initialSupply;              
  totalSupply = initialSupply;                        
  name = tokenName;                                   
  symbol = tokenSymbol;                               
  decimals = decimalUnits;                            
}
